33	/**
34	 * Enumerate the legal actions for the CURRENT player. Pure: derives everything
35	 * from `state`, never mutates it, and uses no randomness. Each emitted action is
36	 * constructed to satisfy applyAction's validation (so it never throws).
37	 *
38	 * 1. BUILD — single-piece building blocks. With budget >= 1, for every board hex
39	 *    emit a single-piece factory build and/or base build wherever the legality
40	 *    predicate holds. The agent composes multi-piece builds by greedy sequencing
41	 *    (spec §11); move-gen never enumerates combinations.
42	 * 2. ATTACK — deterministic representatives. For each valid outer target and each
43	 *    commitment level c in 3..min(6, eligibleAttackers), emit ONE action: the c
44	 *    eligible attacker bases NEAREST the target (distance asc, tie by ascending
45	 *    key). This bounds the action space to one representative per (target, level)
46	 *    rather than every attacker subset. Single-AttackDecl actions only; the agent
47	 *    may chain multi-attacks.
48	 * 3. PASS — included if config.allowPass is true, OR if no build/attack action was
49	 *    generated (a stuck player always has at least `pass` so the game progresses).
50	 */
51	export function legalActions(state: GameState): Action[] {
52	  const player = currentPlayer(state);
53	  const alliance = state.players[player]!.alliance;
54	  const isAlly = (id: PlayerId): boolean => alliance.includes(id);
55	  const range = state.config.attackRange;
56	  const actions: Action[] = [];
57	
58	  // 1. BUILD — one single-piece action per legal placement.
59	  if (buildBudget(state, player) >= 1) {
60	    for (const h of state.board.hexes) {
