62	        actions.push({ kind: "build", pieces: [{ type: "factory", hex: h }] });
63	      }
64	      if (isLegalBasePlacement(state, player, h)) {
65	        actions.push({ kind: "build", pieces: [{ type: "base", hex: h }] });
66	      }
67	    }
68	  }
69	
70	  // 2. ATTACK — one representative per (valid outer target, commitment level).
71	  const myFresh = state.bases.filter((b) => isAlly(b.owner) && b.state === "fresh");
72	  // Candidate targets: every opponent (non-ally) base.
73	  for (const targetBase of state.bases) {
74	    if (isAlly(targetBase.owner)) continue;
75	    const opponent = targetBase.owner;
76	    const oppBases = state.bases.filter((b) => b.owner === opponent);
77	    const t = targetBase.hex;
